  double s = 0, v = 0;
  for (int i = 0; i < n; i++) {
    const double r = c[i].red / 65535.0, g = c[i].green / 65535.0,
                 b = c[i].blue / 65535.0;
    const double hi = fmax(r, fmax(g, b)), lo = fmin(r, fmin(g, b));
    s += hi > 0 ? (hi - lo) / hi : 0;
    v += hi;
  }
  *sat = s / n;
  *val = v / n;
}

