  if (!pm || pm->depth != 1) return 0;
  float stack[32];
  float *cross = n <= 32 ? stack : (float *)malloc((size_t)n * sizeof(float));
  if (!cross) return 1;
  int ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
