  if (image == None) return;
  const struct XshimPixmap *pm = (const struct XshimPixmap *)(uintptr_t)image;
  uint16_t *row = (uint16_t *)malloc((size_t)c->w * sizeof(uint16_t));
  if (row) {
    for (int y = 0; y < c->h; y++) {
